"""Catalogue metadata is read from the current corpus, never generated by an LLM."""
import json
import re
from common import file_hash

def ordinal_selection(text):
    match=re.fullmatch(r'(?:请|就|先)?(?:选择|选中|选|看)?第([一二12])(?:个|款)[。！!？?\s]*',text.strip())
    return {'一':0,'1':0,'二':1,'2':1}.get(match[1]) if match else None

def catalogue_request(text):
    """High-precision metadata grammar; other paraphrases use semantic routing."""
    if re.search(r'什么是|什么叫|是什么意思',text):return None
    if re.search(r'价格|售价|多少钱|库存|有货|订单|退款|退货|下单',text):return None
    noun=bool(re.search(r'商品|产品|资料库|商品库',text))
    listing=noun and bool(re.search(r'有哪些|有哪几|列[出下一]|罗列|清单|目录|展示|(?:编号|编码).*(?:名称|名字)|(?:名称|名字).*(?:编号|编码)',text))
    facts=bool(re.search(r'宽度|重量|材质|承重|全部参数|清洁方法|规格',text))
    if listing and facts:return 'mixed_catalog'
    if listing:return 'catalog'
    if noun and re.search(r'品类|类别|只(?:包含|有|收录)|除了.*还有|之外.*(?:还有|收录)',text):return 'coverage'
    return None

class Catalogue:
    def __init__(self,corpus,documents):
        self.documents={d['sku']:d for d in documents}
        records=json.loads((corpus/'selected-products.json').read_text('utf-8'))
        self.types=sorted({t['value'] for r in records if r['item']['item_id'] in self.documents for t in r['item'].get('product_type',[])})
        self.sources={name:file_hash(corpus/name) for name in ('documents.json','selected-products.json')}
        self.manifest={'product_count':len(self.documents),'product_types':self.types,
                       'type_labels':[{'CHAIR':'椅子'}.get(t,t) for t in self.types],
                       'live_inventory':False,'other_categories_search':False,'web_search':False,
                       'source':'current_local_catalogue_metadata','sha256':self.sources}

    def items(self,exclude=()):
        return [{'sku':sku,'title':self.documents[sku]['title']} for sku in sorted(self.documents) if sku not in exclude]

    def coverage(self):
        kinds='、'.join(self.manifest['type_labels']) or '未分类'
        return (f"当前本地资料库收录{len(self.documents)}个商品，品类仅有{kinds}。没有其他品类的商品资料，不能通过提供名称或编号查询未收录商品。"
                '可以讨论其他品类的一般知识；这不代表已接入其商品参数、实时库存、价格或店铺政策。输入“商品列表”可查看收录编号和原始名称。')

    def render(self,items):
        return (f"当前资料库可查询的商品（共{len(items)}项；编号与原始名称来自本地目录，不代表实时在售或有货）：\n"+
                '\n'.join(f"{i}. {item['sku']} | {item['title']}" for i,item in enumerate(items,1))+
                '\n可直接回复编号或说“第一个/第二个”，再问具体参数；商品事实会另行检索页面证据。')
